#include "sql_dump.hpp"
#include <algorithm>
#include <cctype>
#include <charconv>
#include <fstream>
#include <iterator>
#include <regex>
#include <stdexcept>
#include <utility>
namespace mycelia::sql {
namespace {
std::string trim(std::string_view s){auto a=s.find_first_not_of(" \t\r\n");if(a==s.npos)return {};auto b=s.find_last_not_of(" \t\r\n");return std::string(s.substr(a,b-a+1));}
std::string lower(std::string s){std::transform(s.begin(),s.end(),s.begin(),[](unsigned char c){return static_cast<char>(std::tolower(c));});return s;}
bool starts(std::string_view s,std::string_view word){if(s.size()<word.size())return false;for(size_t i=0;i<word.size();++i)if(std::toupper(static_cast<unsigned char>(s[i]))!=word[i])return false;return true;}
std::string remove_comments(std::string_view s){std::string out; out.reserve(s.size());char quote=0; bool esc=false;for(size_t i=0;i<s.size();){char c=s[i];if(quote){out+=c;if(esc)esc=false;else if(c=='\\')esc=true;else if(c==quote)quote=0;++i;continue;}if(c=='\''||c=='"'){quote=c;out+=c;++i;continue;}if(c=='/'&&i+1<s.size()&&s[i+1]=='*'){bool version=i+2<s.size()&&s[i+2]=='!';(void)version;i+=2;while(i+1<s.size()&&!(s[i]=='*'&&s[i+1]=='/'))++i;i=std::min(i+2,s.size());out+=' ';continue;}if((c=='#'||(c=='-'&&i+1<s.size()&&s[i+1]=='-'))&&(i==0||s[i-1]=='\n'||s[i-1]=='\r')){while(i<s.size()&&s[i]!='\n')++i;continue;}out+=c;++i;}return out;}
std::vector<std::string> split(std::string_view s,char delimiter){std::vector<std::string> r;size_t start=0;char quote=0;bool esc=false;int depth=0;for(size_t i=0;i<s.size();++i){char c=s[i];if(quote){if(esc)esc=false;else if(c=='\\')esc=true;else if(c==quote)quote=0;continue;}if(c=='\''||c=='"'){quote=c;continue;}if(c=='('){++depth;continue;}if(c==')'){--depth;continue;}if(c==delimiter&&depth==0){auto t=trim(s.substr(start,i-start));if(!t.empty())r.push_back(std::move(t));start=i+1;}}auto t=trim(s.substr(start));if(!t.empty())r.push_back(std::move(t));return r;}
std::pair<std::string,size_t> identifier(std::string_view s,size_t pos){while(pos<s.size()&&std::isspace(static_cast<unsigned char>(s[pos])))++pos;if(pos==s.size())return {{},pos};char q=s[pos];if(q=='`'||q=='"'||q=='\''){auto end=s.find(q,pos+1);if(end==s.npos)return {{},pos};return {std::string(s.substr(pos+1,end-pos-1)),end+1};}size_t start=pos;while(pos<s.size()&&(std::isalnum(static_cast<unsigned char>(s[pos]))||s[pos]=='_'||s[pos]=='$'))++pos;return {std::string(s.substr(start,pos-start)),pos};}
std::optional<size_t> keyword(std::string_view s,std::string_view word){for(size_t i=0;i+word.size()<=s.size();++i){if((i==0||!std::isalnum(static_cast<unsigned char>(s[i-1])))&&starts(s.substr(i),word)&&(i+word.size()==s.size()||!std::isalnum(static_cast<unsigned char>(s[i+word.size()]))))return i;}return {};}
Value literal(std::string_view raw){auto t=trim(raw);auto lo=lower(t);if(lo=="null")return nullptr;if(lo=="true")return true;if(lo=="false")return false;if(t.size()>=2&&(t[0]=='\''||t[0]=='"')&&t.back()==t[0]){std::string v;for(size_t i=1;i+1<t.size();++i){if(t[i]=='\\'&&i+2<t.size()){char x=t[++i];switch(x){case 'n':v+='\n';break;case 'r':v+='\r';break;case 't':v+='\t';break;case '0':v+='\0';break;case '\\':v+='\\';break;case '\'':v+='\'';break;case '"':v+='"';break;default:v+='\\';v+=x;}}else v+=t[i];}return v;}if(t.size()>2&&t[0]=='0'&&(t[1]=='x'||t[1]=='X'))return t;std::int64_t integer{};auto [end,err]=std::from_chars(t.data(),t.data()+t.size(),integer);if(err==std::errc{}&&end==t.data()+t.size())return integer;static const std::regex floating(R"(^[-+]?(?:\d+\.\d*|\.\d+|\d+[eE][-+]?\d+)(?:[eE][-+]?\d+)?$)");if(std::regex_match(t,floating)){try{return std::stod(t);}catch(...){}}return t;}
std::vector<std::string> groups(std::string_view s){std::vector<std::string> out;char quote=0;bool esc=false;int depth=0;size_t begin=0;for(size_t i=0;i<s.size();++i){char c=s[i];if(quote){if(esc)esc=false;else if(c=='\\')esc=true;else if(c==quote)quote=0;continue;}if(c=='\''||c=='"'){quote=c;continue;}if(c=='('){if(depth++==0)begin=i+1;}else if(c==')'){if(depth>0&&--depth==0)out.emplace_back(s.substr(begin,i-begin));}}return out;}
}
DumpImage DumpImage::parse(std::string_view input){DumpImage image;auto clean=remove_comments(input);for(const auto& statement:split(clean,';')){auto s=trim(statement);if(starts(s,"CREATE TABLE")){size_t p=12;while(p<s.size()&&std::isspace(static_cast<unsigned char>(s[p])))++p;if(starts(s.substr(p),"IF NOT EXISTS"))p+=13;auto [name,end]=identifier(s,p);if(name.empty())continue;auto key=lower(name);if(!image.tables_.contains(key)){image.order_.push_back(key);image.tables_.emplace(key,Table{name,{},{}});}auto& table=image.tables_.at(key);auto l=s.find('(',end);auto r=s.rfind(')');if(l==s.npos||r==s.npos||l>=r)continue;std::vector<std::string> cols;for(const auto& field:split(std::string_view(s).substr(l+1,r-l-1),',')){auto up=field;if(starts(up,"PRIMARY ")||starts(up,"KEY ")||starts(up,"UNIQUE ")||starts(up,"INDEX ")||starts(up,"CONSTRAINT ")||starts(up,"FOREIGN ")||starts(up,"FULLTEXT ")||starts(up,"SPATIAL "))continue;auto [col,_]=identifier(field,0);if(!col.empty())cols.push_back(std::move(col));}table.columns=std::move(cols);
}else if(starts(s,"INSERT")){size_t p=6;while(p<s.size()&&std::isspace(static_cast<unsigned char>(s[p])))++p;if(starts(s.substr(p),"IGNORE"))p+=6;while(p<s.size()&&std::isspace(static_cast<unsigned char>(s[p])))++p;if(!starts(s.substr(p),"INTO"))continue;p+=4;auto [name,end]=identifier(s,p);if(name.empty())continue;auto key=lower(name);if(!image.tables_.contains(key)){image.order_.push_back(key);image.tables_.emplace(key,Table{name,{},{}});}auto& table=image.tables_.at(key);p=end;while(p<s.size()&&std::isspace(static_cast<unsigned char>(s[p])))++p;std::optional<std::vector<std::string>> cols;if(p<s.size()&&s[p]=='('){auto e=s.find(')',p);if(e==s.npos)continue;cols.emplace();for(const auto& col:split(std::string_view(s).substr(p+1,e-p-1),',')){auto [v,_]=identifier(col,0);if(!v.empty())cols->push_back(v);}p=e+1;}auto v=keyword(std::string_view(s).substr(p),"VALUES");if(!v)continue;auto rows=groups(std::string_view(s).substr(p+*v+6));for(auto& row:rows){auto tokens=split(row,',');std::vector<std::string> names;if(cols)names=*cols;else if(table.columns.size()==tokens.size())names=table.columns;else for(size_t j=0;j<tokens.size();++j)names.push_back("col_"+std::to_string(j));if(cols&&table.columns.empty())table.columns=*cols;Row record;for(size_t j=0;j<names.size();++j)record[names[j]]=j<tokens.size()?literal(tokens[j]):Value{nullptr};table.rows.push_back(std::move(record));}
}}return image;}
DumpImage DumpImage::from_file(const std::filesystem::path& path){std::ifstream in(path,std::ios::binary);if(!in)throw std::runtime_error("Cannot open SQL dump: "+path.string());std::string contents((std::istreambuf_iterator<char>(in)),{});return parse(contents);}
std::vector<std::string> DumpImage::list_tables() const {std::vector<std::string> out;for(auto& key:order_){auto& t=tables_.at(key);if(!t.columns.empty()||!t.rows.empty())out.push_back(t.name);}return out;}
std::vector<Row> DumpImage::fetch_rows(std::string_view table,std::optional<std::string_view> where,std::optional<size_t> limit)const{auto it=tables_.find(lower(std::string(table)));if(it==tables_.end())return {};std::optional<std::pair<std::string,Value>> filter;if(where){auto str=trim(*where);auto p=str.find('=');if(p==str.npos)throw std::invalid_argument("Only column=value filters are supported");auto key=trim(std::string_view(str).substr(0,p));if(key.empty()||!std::isalpha(static_cast<unsigned char>(key[0]))&&key[0]!='_')throw std::invalid_argument("Invalid WHERE column");for(char c:key)if(!std::isalnum(static_cast<unsigned char>(c))&&c!='_'&&c!='$')throw std::invalid_argument("Invalid WHERE column");filter=std::make_pair(key,literal(std::string_view(str).substr(p+1)));}std::vector<Row> out;for(const auto& row:it->second.rows){if(filter){auto v=row.find(filter->first);if(v==row.end()||v->second!=filter->second)continue;}if(limit&&out.size()>=*limit)break;out.push_back(row);}return out;}
size_t DumpImage::row_count()const{size_t n=0;for(auto& [_,t]:tables_)n+=t.rows.size();return n;}
std::string display(const Value& value){return std::visit([](const auto& v)->std::string{using T=std::decay_t<decltype(v)>;if constexpr(std::is_same_v<T,std::nullptr_t>)return "NULL";else if constexpr(std::is_same_v<T,bool>)return v?"True":"False";else if constexpr(std::is_same_v<T,std::string>)return v;else return std::to_string(v);},value);}
}
